-- GEGENEREERD door scripts/genereer-artikelen.mjs uit de Teamleader-artikelcatalogus (97 artikelen).
-- Voegt de artikelen toe aan het bedrijf met slug 'kernkozijnen'. Opnieuw uitvoeren verandert bestaande artikelen niet.
-- Prijs incl. btw = prijs excl. btw x 1,174 (21% over 70% en 9% over 30% van het bedrag excl. btw).

insert into public.artikelen (tenant_id, groep, code, naam, omschrijving, eenheid, verkoopprijs_excl, verkoopprijs_incl, btw_tarief_bron, actief)
select t.id, v.groep, v.code, v.naam, v.omschrijving, v.eenheid, v.excl, v.incl, v.btw, v.actief
from public.tenants t
cross join (values
  ('01 - Kozijnen Schüco LivIng 82', 'SCH-RAAM', 'Raamkozijn — Schüco LivIng 82', 'Schüco LivIng 82: 7-kamerprofiel, bouwdiepte 82 mm, Uf 0,92 W/m²K, levertijd 6 tot 8 weken. All-in: profiel, HR++ 24 mm beglazing, kunststof stelkozijn, SKG** RC2-sluitwerk, demontage en afvoer van het bestaande kozijn, montage door eigen monteurs en 10 jaar garantie. Uitvoering wit RAL 9010. De indeling — vast glas, draai-kiep, stolp, meerdelig — beschrijf je op de offerteregel; het prijsverschil loopt via de m²-regel. Prijs geldt bij standaardmaat 1000 × 1200 mm (1,20 m²).', 'stuk', 1735.54, round(1735.54 * 1.174, 2), 21, false),
